     1	import { spawnSync } from "child_process";
     2	
     3	export interface WireMessage {
     4	  key: string;
     5	  payload: string;
     6	}
     7	
     8	export interface PublishResult {
     9	  accepted: number;
    10	  batch: number;
    11	}
    12	
    13	export interface ConsumedMessage {
    14	  offset: number;
    15	  key: string;
    16	  payload: string;
    17	}
    18	
    19	export class MqpubError extends Error {
    20	  constructor(readonly code: string, readonly exitStatus: number | null) {
    21	    super(`mqpub ${code} (exit ${exitStatus})`);
    22	  }
    23	}
    24	
    25	/** 사내 메시지 발행 CLI(mqpub 3.x) 래퍼 */
    26	export class MqpubClient {
    27	  constructor(private readonly bin: string, private readonly spoolDir: string) {}
    28	
    29	  private run(args: string[], input?: string): string {
    30	    const r = spawnSync(this.bin, args, {
    31	      input,
    32	      encoding: "utf8",
    33	      env: { ...process.env, MQPUB_SPOOL: this.spoolDir },
    34	    });
    35	    if (r.error) throw r.error;
    36	    if (r.status !== 0) {
    37	      const code = /E\d+/.exec(r.stderr)?.[0] ?? "E?";
    38	      throw new MqpubError(code, r.status);
    39	    }
    40	    return r.stdout;
    41	  }
    42	
    43	  /** 메시지들을 한 배치로 발행한다. */
    44	  publish(topic: string, messages: WireMessage[]): PublishResult {
    45	    if (messages.length === 0) return { accepted: 0, batch: 0 };
    46	    const body = messages.map((m) => `${m.key}\t${m.payload}`).join("\n") + "\n";
    47	    const out = this.run(["publish", "-t", topic], body);
    48	    const m = /^accepted (\d+) batch (\d+)$/m.exec(out);
    49	    if (!m) throw new MqpubError("unparsed-output", 0);
    50	    return { accepted: Number(m[1]), batch: Number(m[2]) };
    51	  }
    52	
    53	  /** offset 부터 끝까지 읽는다. */
    54	  consume(topic: string, fromOffset: number): ConsumedMessage[] {
    55	    const out = this.run(["consume", "-t", topic, "-o", String(fromOffset)]);
    56	    const rows: ConsumedMessage[] = [];
    57	    for (const line of out.split("\n")) {
    58	      if (line === "") continue;
    59	      const [off, key, ...rest] = line.split("\t");
    60	      rows.push({ offset: Number(off), key, payload: rest.join("\t") });
    61	    }
    62	    return rows;
    63	  }
    64	}
=== src/messaging/payloadCodec.ts
     1	import { Notification } from "../domain/notification";
     2	import { isEventKind } from "../domain/order";
     3	
     4	const VERSION = 2;
     5	const MAX_PAYLOAD = 900;
     6	
     7	interface WirePayload {
     8	  v: number;
     9	  o: string;
    10	  c: string;
    11	  k: string;
    12	}
    13	
    14	/** 탭·개행·제어문자는 와이어 형식(<key>TAB<payload>)을 깨므로 제거한다. */
    15	function scrub(s: string): string {
    16	  return s.replace(/[\u0000-\u001f\u007f]/g, "");
    17	}
    18	
    19	export function encodePayload(n: Notification): string {
    20	  const body: WirePayload = { v: VERSION, o: scrub(n.orderNo), c: scrub(n.customerId), k: n.kind };
    21	  const json = JSON.stringify(body);
    22	  if (json.length > MAX_PAYLOAD) throw new Error("payload too large");
    23	  return json;
    24	}
    25	
    26	export function decodePayload(raw: string): Notification | null {
    27	  let body: Partial<WirePayload>;
    28	  try {
    29	    body = JSON.parse(raw) as Partial<WirePayload>;
    30	  } catch {
    31	    return null;
    32	  }
    33	  if (body.v !== VERSION && body.v !== 1) return null;
    34	  if (typeof body.o !== "string" || typeof body.c !== "string" || !isEventKind(body.k)) return null;
    35	  return { orderNo: body.o, customerId: body.c, kind: body.k };
    36	}
