    25	
    26	/** 2026-10-07 → 261007 */
    27	export function compactDate(placedOn: string): string {
    28	  const m = /^20(\d{2})-(\d{2})-(\d{2})$/.exec(placedOn);
    29	  if (!m) throw new Error("invalid placedOn");
    30	  return `${m[1]}${m[2]}${m[3]}`;
    31	}
    32	
    33	/**
    34	 * 주문번호 체계
    35	 *   자사몰:     O<yymmdd>-<일련 5자리>            예) O261007-00042
    36	 *   오픈마켓:   M-<제휴사 4자>-<yymmdd>-<일련 6자리> 예) M-GMKT-261007-000123
    37	 */
    38	export function formatOrderNo(channel: Channel, placedOn: string, seq: number, partner?: string): string {
    39	  const d = compactDate(placedOn);
    40	  if (channel === "direct") return `O${d}-${String(seq).padStart(5, "0")}`;
    41	  if (!partner || !/^[A-Z]{4}$/.test(partner)) throw new Error("invalid partner");
    42	  return `M-${partner}-${d}-${String(seq).padStart(6, "0")}`;
    43	}

