    25	/** 운영 화면용 회차 리포트 — 계획된 알림마다 발송 여부를 보여 준다. */
    26	export function buildDispatchReport(run: DispatchRun, customers: CustomerRepository): DispatchReport {
    27	  const lines: DispatchReportLine[] = run.planned.map((n) => {
