     1	import { createHash } from "crypto";
     2	import { normalizeMobile } from "../util/format";
     3	
     4	export interface SmsReceipt {
     5	  ok: boolean;
     6	  receiptId?: string;
     7	  reason?: string;
     8	}
     9	
    10	export interface SmsGateway {
    11	  send(from: string, to: string, text: string): SmsReceipt;
    12	}
    13	
    14	/** 문자 대행사 모의 게이트웨이 — 받은 문자를 번호별 수신함에 쌓는다. */
    15	export class InMemorySmsGateway implements SmsGateway {
    16	  private readonly inboxes = new Map<string, string[]>();
    17	  private sent = 0;
    18	
    19	  send(from: string, to: string, text: string): SmsReceipt {
    20	    const number = normalizeMobile(to);
    21	    if (!number) return { ok: false, reason: "invalid-number" };
    22	    if (text.length === 0) return { ok: false, reason: "empty-body" };
    23	    this.sent++;
    24	    const list = this.inboxes.get(number) ?? [];
    25	    list.push(text);
    26	    this.inboxes.set(number, list);
    27	    const receiptId = createHash("sha1").update(`${from}|${number}|${this.sent}|${text}`).digest("hex").slice(0, 12);
    28	    return { ok: true, receiptId };
    29	  }
    30	
    31	  inbox(phone: string): string[] {
    32	    const number = normalizeMobile(phone);
    33	    return number ? [...(this.inboxes.get(number) ?? [])] : [];
    34	  }
    35	}
